-- ============================================
-- LUMA — Thème 4 : MOYEN 1/3 x4 — Un vol annulé à gérer
-- ============================================


update scenarios set content = '{"characters": {"agent": "l''agent de la compagnie"}, "start_node": "n1", "nodes": {"n1": {"speaker": "announcement", "text": "Attention passengers, flight 224 to Chicago has been cancelled due to weather conditions.", "text_fr": "Attention passagers, le vol 224 pour Chicago a été annulé en raison des conditions météo.", "choices": [{"text": "(Head to the customer service desk immediately.)", "text_fr": "(Va au comptoir service client immédiatement.)", "next": "n2"}, {"text": "(Check the airline app first for automatic rebooking options.)", "text_fr": "(Vérifie d''abord l''appli de la compagnie pour des options de reréservation automatique.)", "next": "n2b"}]}, "n2": {"speaker": "agent", "text": "I''m sorry about the cancellation. Let me see what options we have for you.", "text_fr": "Je suis désolé pour l''annulation. Laissez-moi voir quelles options on a pour vous.", "choices": [{"text": "Thank you, I really need to get there by tomorrow if possible.", "text_fr": "Merci, j''ai vraiment besoin d''y être demain si possible.", "next": "n3"}, {"text": "I appreciate it — what''s causing the delay exactly?", "text_fr": "J''apprécie — qu''est-ce qui cause le retard exactement ?", "next": "n3b"}]}, "n2b": {"speaker": "you_thought", "text": "(The app shows a rebooking option, but the desk might have better ones.)", "text_fr": "(L''appli montre une option de reréservation, mais le comptoir en a peut-être de meilleures.)", "choices": [{"text": "(Go to the desk anyway to check for better options.)", "text_fr": "(Va au comptoir quand même pour vérifier de meilleures options.)", "next": "n2"}]}, "n3": {"speaker": "agent", "text": "Let me check — there''s a flight tomorrow morning at 8am with availability.", "text_fr": "Laissez-moi vérifier — il y a un vol demain matin à 8h avec de la disponibilité.", "choices": [{"text": "That works, please book me on that one.", "text_fr": "Ça marche, réservez-moi sur celui-là s''il vous plaît.", "next": "n4"}, {"text": "Is there anything sooner, even through a connection?", "text_fr": "Il y a quelque chose de plus tôt, même avec une correspondance ?", "next": "n4b"}]}, "n3b": {"speaker": "agent", "text": "A severe storm system is affecting the whole region right now.", "text_fr": "Un système orageux sévère affecte toute la région en ce moment.", "choices": [{"text": "That makes sense, safety first. What are my options then?", "text_fr": "Ça se comprend, la sécurité avant tout. Quelles sont mes options alors ?", "next": "n4"}]}, "n4": {"speaker": "agent", "text": "I''ll get that booked for you right away.", "text_fr": "Je vous réserve ça tout de suite.", "choices": [{"text": "Thank you, and will the airline cover a hotel for tonight?", "text_fr": "Merci, et la compagnie couvre un hôtel pour ce soir ?", "next": "n5"}]}, "n4b": {"speaker": "agent", "text": "Let me check connecting options... there''s one through Denver, arriving tonight at 11pm.", "text_fr": "Laissez-moi vérifier les correspondances... il y en a une via Denver, arrivant ce soir à 23h.", "choices": [{"text": "That''s later, but it gets me there sooner overall — let''s do that.", "text_fr": "C''est plus tard, mais ça m''amène plus tôt au final — faisons ça.", "next": "n5"}, {"text": "Actually, I''d rather rest and take the direct flight tomorrow.", "text_fr": "En fait, je préfère me reposer et prendre le vol direct demain.", "next": "n4"}]}, "n5": {"speaker": "agent", "text": "Yes, since this was a weather-related cancellation, we can offer a hotel voucher.", "text_fr": "Oui, comme c''était une annulation liée à la météo, on peut offrir un bon d''hôtel.", "choices": [{"text": "That''s very helpful, thank you.", "text_fr": "C''est très utile, merci.", "next": "n6"}, {"text": "Perfect, and is there a meal voucher too, by any chance?", "text_fr": "Parfait, et il y a un bon repas aussi, par hasard ?", "next": "n6b"}]}, "n6": {"speaker": "agent", "text": "Here''s your hotel voucher and new boarding pass for tomorrow''s flight.", "text_fr": "Voici votre bon d''hôtel et votre nouvelle carte d''embarquement pour le vol de demain.", "choices": [{"text": "Thank you so much for sorting this out.", "text_fr": "Merci beaucoup d''avoir arrangé ça.", "next": "n7"}]}, "n6b": {"speaker": "agent", "text": "Of course, here''s a meal voucher as well, for the inconvenience.", "text_fr": "Bien sûr, voici aussi un bon repas, pour le désagrément.", "choices": [{"text": "I really appreciate all of this, thank you.", "text_fr": "J''apprécie vraiment tout ça, merci.", "next": "n7"}]}, "n7": {"speaker": "agent", "text": "You''re very welcome. I''m sorry again for the disruption to your trip.", "text_fr": "Je vous en prie. Encore désolé pour la perturbation de votre voyage.", "choices": [{"text": "These things happen, thank you for handling it so well.", "text_fr": "Ça arrive, merci de l''avoir si bien géré.", "next": "end_handled"}]}, "end_handled": {"speaker": "agent", "text": "Have a comfortable night, and safe travels tomorrow!", "text_fr": "Passez une nuit confortable, et bon voyage demain !", "end": true, "ending_label": "Vol annulé géré avec calme et efficacité ✈️🏨"}}}'::jsonb, is_playable = true
where title = 'Un vol annulé à gérer'
  and theme_id = (select id from scenario_themes where position = 4 and language_id = (select id from languages where code = 'en'));
